const mineBefore109=mine;
mine=function(){mineBefore109();$('#app').insertAdjacentHTML('beforeend','<section class="panel"><h2>学习回顾</h2><p class="tip">查看检验历史、待练点与对应课程。</p><button class="primary" id="learning-history">能力档案</button></section>');$('#learning-history').onclick=history109};
function history109(){session=null;const history=state.assessments||[];$('#app').innerHTML='<button class="link" id="history-back">← 返回我的</button><h1>学习回顾</h1><p class="tip">记录任务表现，不以作答次数代表掌握程度。</p>'+history.slice().reverse().map((h,i)=>'<section class="panel"><h2>'+['认牌与观察','单牌情境解释','三牌综合解读'][h.stage]+'</h2><small>'+E(h.date)+'</small>'+h.results.map(r=>{const q=FLOW108.bank.find(q=>q.id===r.qid);return '<div class="history-evidence"><strong>'+E(r.dimension||q?.category||'综合任务')+'</strong><p>'+E(q?.question||r.prompt||r.qid)+'</p><span>'+(r.independent===false?'提示后作答':r.correct?'独立回答正确':'待练习')+'</span>'+((q||r.courseIds)?'<button class="link" data-history-course="'+(q?.courseIds||r.courseIds)[0]+'">回看相关课程</button>':'')+'</div>'}).join('')+'<button class="secondary" data-retest="'+h.stage+'">再检验一次</button></section>').join('')+(history.length?'':'<div class="empty">还没有阶段检验记录。可随时进入课程首页开始检验。</div>');$('#history-back').onclick=()=>navigate('mine');document.querySelectorAll('[data-retest]').forEach(b=>b.onclick=()=>assessment108(Number(b.dataset.retest)));document.querySelectorAll('[data-history-course]').forEach(b=>b.onclick=()=>{start(b.dataset.historyCourse);session.historyOrigin=true;remember(false);lessonView()})}
render();
